__NUXT_JSONP__("/jp/how-to-apply", (function(a,b){return {data:[{details:{slug:"jp",pageTitle:"お申し込み方法 | Mentor Language Institute",pageDescription:a,title:"お申し込み方法",image:"\u002Fimages\u002Fhow-to-apply\u002Fhow-to-apply\u002Fstaff.jpg",category:[{title:a,content:[{description:["Mentor Languega Instituteへのお申込みをご検討いただき、誠にありがとうございます。\u003Cbr \u002F\u003Eお申込み方法は、現在の居住地、ビザや受講される期間によって異なります。質問にお答えいただき、適切な申し込み方法をご選択ください。"]}],subtitle:"現在、住んでいらっしゃる国はどちらですか？",description:"現在滞在されている国よって申込方法が異なります。",other_info:["\u003Ca class='btn btn-primary text-center' href='\u002Fjp\u002Fhow-to-apply\u002Foverseas'\u003E日本からの申込\u003C\u002Fa\u003E",b,"\u003Ca class='btn btn-primary text-center' href='\u002Fjp\u002Fhow-to-apply\u002Fstudent-visa-f1\u002Ftransfer-students'\u003E米国内からの転校\u003C\u002Fa\u003E",b,"\u003Ca class='btn btn-primary text-center' href='\u002Fjp\u002Fhow-to-apply\u002Fstudent-visa-f1\u002Fchange-of-status'\u003Eその他\u003C\u002Fa\u003E"]}],content:["MLIは英語以外にも合計 \u003Cspan style=\"color: #ff0000; font-weight: bold;\"\u003E8言語で皆様の質問に対応しております。\u003C\u002Fspan\u003E現在の状況や、分類がお分かりにならない方はお気軽にお問合せページよりお聞き下さい。"],hasBrochure:true,dir:"\u002Fhow-to-apply",path:"\u002Fhow-to-apply\u002Fjp",extension:".json",createdAt:"2026-10-22T16:31:29.640Z",updatedAt:"2025-05-26T12:06:27.790Z"}}],fetch:{},mutations:void 0}}("MLIへの各種お申し込み方法はこちら","\u003Cspan class='text-center'\u003Eor\u003C\u002Fspan\u003E")));